// nom ressemblant : on change une lettre (comme « Mesi », « Zidanne »)
function albAlter(n) {
  const acc = { a: "à", e: "è", i: "ì", o: "ò", u: "ù", "é": "è", "á": "à", "í": "ì", "ó": "ò", "ú": "ù" };
  const w = n.split(" "), last = w[w.length - 1];
  let out = last;
  const m = last.match(/^(.*[aeiouyéáíóú])([bcdfglmnprstvz])([aeiouyéáíóú].*)$/i);
  if (m && last.length > 3 && !/[A-Z]$/.test(m[2])) out = m[1] + m[2] + m[2] + m[3];          // on double une consonne
  else { const k = [...last].reverse().findIndex(ch => acc[ch]); if (k >= 0) { const i = last.length - 1 - k; out = last.slice(0, i) + acc[last[i]] + last.slice(i + 1); } else out = last + "e"; }
  w[w.length - 1] = out;
  return w.join(" ");
}
const ALB_POS = ["G", "G", "D", "D", "D", "D", "D", "D", "M", "M", "M", "M", "M", "A", "A", "A", "A", "A"];
const ALB_TEAMS = ALB_TEAMS_RAW.trim().split("\n").map(l => { const [g, code, name, c1, c2, pl] = l.split("|"); return { g, code, name, c1, c2, pl: pl.split(",").slice(0, 18).map(albAlter) }; });
// la liste des vignettes : 00 à 04, puis 20 par pays, puis les 12 BONUS
const ALB = [];
const ALB_SPECIAL_TXT = ["Le ciseau de l'âne", "La Coupe (moitié gauche)", "La Coupe (moitié droite)", "Mohuss FC · Dylan FC · Zakaka FC", "Dylan FC"];
ALB_SPECIAL_TXT.forEach((n, i) => ALB.push({ k: "sp", code: "0" + i, n }));
const ALB_STARS = { BRA: 5, GER: 4, ARG: 3, FRA: 2, URU: 2, ENG: 1, ESP: 1 };   // étoiles = Coupes du Monde gagnées
ALB_TEAMS.forEach((t, ti) => {
  // comme dans le vrai album : n°1 l'écusson, n°13 la photo d'équipe, les autres numéros pour les 18 joueurs
  let j = 0;
  for (let num = 1; num <= 20; num++) {
    if (num === 1) ALB.push({ k: "badge", t: ti, code: t.code + " 1", n: "Écusson", num });
    else if (num === 13) ALB.push({ k: "team", t: ti, code: t.code + " 13", n: "Photo d'équipe", num });
    else { ALB.push({ k: "pl", t: ti, code: t.code + " " + num, n: t.pl[j], p: ALB_POS[j], num }); j++; }
  }
});
const ALB_BONUS = ["Pelè", "Maradonna", "Zidanne", "Ronaldô", "Mesi", "C. Ronaldoo", "Drogbà", "Weahh", "Eto'oo", "Henrri", "Beckenbauerr", "Cruijjf"];
const ALB_BONUS_C = ["Brésil", "Argentine", "France", "Brésil", "Argentine", "Portugal", "Côte d'Ivoire", "Liberia", "Cameroun", "France", "Allemagne", "Pays-Bas"];
ALB_BONUS.forEach((n, i) => ALB.push({ k: "bonus", code: "B" + (i + 1), n, c: ALB_BONUS_C[i] }));
const ALB_NEED = ALB.filter(s => s.k !== "bonus").length;          // 965 vignettes pour finir l'album
const ALB_NORMAL = ALB.map((s, i) => i).filter(i => ALB[i].k !== "bonus");
const ALB_BONUS_IDS = ALB.map((s, i) => i).filter(i => ALB[i].k === "bonus");
const ALB_PRICE = 100000, ALB_PER = 7, ALB_BONUS_CH = 0.01, ALB_LEVELS = 10;
function albOf(u) { if (!u.alb) u.alb = { inv: {}, stuck: [], done: false, packs: 0 }; if (!u.alb.inbox) u.alb.inbox = []; return u.alb; }
const ALB_SELL = 5000, ALB_SELL_BONUS = 50000;          // prix de revente d'un double
const albView = u => { const a = albOf(u); return { inv: a.inv, stuck: a.stuck, done: a.done, packs: a.packs, need: ALB_NEED, price: ALB_PRICE, per: ALB_PER, sell: ALB_SELL, sellB: ALB_SELL_BONUS, inbox: a.inbox }; };
// combien de doubles d'une vignette (ce qu'on peut échanger ou vendre sans s'en priver)
function albSpare(a, id) { const n = a.inv[id] || 0; return a.stuck.includes(id) ? n : Math.max(0, n - 1); }
function albDoublesOf(u) { const a = albOf(u), out = {}; for (const k in a.inv) { const n = albSpare(a, +k); if (n > 0) out[k] = n; } return out; }
function albTake(a, id) { a.inv[id]--; if (!a.inv[id]) delete a.inv[id]; }
function sendAlb(u, extra) { for (const c of clients.values()) if (c.user === u) send(c, Object.assign({ t: "alb", alb: albView(u) }, extra || {})); }
function albDraw() { return Math.random() < ALB_BONUS_CH ? pickOf(ALB_BONUS_IDS) : pickOf(ALB_NORMAL); }
function albGive(u, ids) { const a = albOf(u); for (const id of ids) a.inv[id] = (a.inv[id] || 0) + 1; }
function albCheckDone(u) {
  const a = albOf(u);
  if (a.done) return false;
  const st = new Set(a.stuck);
  if (!ALB_NORMAL.every(i => st.has(i))) return false;
  a.done = true;
  const before = levelOfUser(u), L = before + ALB_LEVELS;               // album complet : +10 niveaux
  monthOf(u); u.bonus = goalsFor(L) - u.stats.gf;
  saveUser(u); pushMe(u); announceLevel(u, before);
  pushFeed(`📒 ${u.name} a complété l'Album 2026 !`);
  return true;
}

