const QUIZ_N = 5, QUIZ_WIN = 300;
function quizOf(u) {
  const d = dayId();
  if (!u.quiz || u.quiz.day !== d) u.quiz = { day: d, n: 0, asked: [], cur: null };
  return u.quiz;
}
function quizSend(c) {
  const u = c.user, z = quizOf(u);
  if (z.n >= QUIZ_N) return send(c, { t: "quiz", left: 0 });
  if (!z.cur) {
    const pool = QUIZ.map((_, i) => i).filter(i => !z.asked.includes(i));
    const qi = pool[Math.floor(Math.random() * pool.length)];
    const order = [0, 1, 2, 3].sort(() => Math.random() - 0.5);
    z.cur = { qi, order }; z.asked.push(qi); saveUser(u);
  }
  const q = QUIZ[z.cur.qi];
  send(c, { t: "quiz", left: QUIZ_N - z.n, q: q.q, a: z.cur.order.map(i => q.a[i]), win: QUIZ_WIN });
}

/* =========================================================
   MODE CLASSÉ : file d'attente, match 1 contre 1, points de rang
   ========================================================= */
const RANK_WIN = 25, RANK_LOSS = 20;
const rankQueue = new Map();          // id du client -> moment où il a commencé à chercher
function rankResult(winU, loseU) {
  const res = {};
  if (winU) { winU.rp = (winU.rp || 0) + RANK_WIN; res[winU.key] = RANK_WIN; saveUser(winU); pushMe(winU); }
  if (loseU) { const before = loseU.rp || 0; loseU.rp = Math.max(0, before - RANK_LOSS); res[loseU.key] = loseU.rp - before; saveUser(loseU); pushMe(loseU); }
  return res;
}
function rankTick() {
  const now = Date.now();
  const q = [...rankQueue.entries()].map(([id, t]) => ({ c: clients.get(id), t })).filter(x => x.c && x.c.user && !x.c.room);
  for (const [id] of rankQueue) if (!clients.get(id) || !clients.get(id).user) rankQueue.delete(id);
  q.sort((a, b) => a.t - b.t);
  const used = new Set();
  for (const a of q) {
    if (used.has(a.c.id)) continue;
    let best = null, bd = 1e9;
    for (const b of q) {
      if (b === a || used.has(b.c.id) || b.c.user === a.c.user) continue;
      const d = Math.abs((a.c.user.rp || 0) - (b.c.user.rp || 0));
      const allow = 150 + 25 * Math.floor((now - Math.min(a.t, b.t)) / 5000);   // plus on attend, plus l'écart permis est grand
      if (d <= allow && d < bd) { bd = d; best = b; }
    }
    if (!best) continue;
    used.add(a.c.id); used.add(best.c.id);
    rankQueue.delete(a.c.id); rankQueue.delete(best.c.id);
    startRankedRoom(a.c, best.c);
  }
}
setInterval(rankTick, 2000);
function startRankedRoom(a, b) {
  const room = {
    code: makeCode(), name: "Match classé", host: a.id, public: false, type: "1v1", mode: "cdm", ranked: true,
    maxPlayers: 2, numTeams: 32, diff: "moyen", state: "lobby", players: new Map(), tour: null, roundTimer: null,
    sideTeam: { A: null, B: null }, match: null,
  };
  rooms.set(room.code, room);
  for (const [c, side] of [[a, "A"], [b, "B"]]) {
    room.players.set(c.id, { id: c.id, name: c.name, role: c.user.role, team: null, side });
    c.room = room.code; c.watching = false;
    send(c, { t: "rankfound", vs: (c === a ? b : a).name, vsRp: (c === a ? b : a).user.rp || 0, code: room.code });
  }
  broadcastRoom(room);
  // 25 secondes pour choisir son pays, sinon on en prend un au hasard
  room.roundTimer = setTimeout(() => {
    if (!rooms.has(room.code) || room.state !== "lobby") return;
    const pool = shuffle(POOLS.cdm.slice());
    for (const s of ["A", "B"]) if (room.sideTeam[s] == null) room.sideTeam[s] = pool.find(t => t !== room.sideTeam.A && t !== room.sideTeam.B);
    startMatchRoom(room);
  }, 25000);
}

