  e.respondWith(fetch(r).then(res => { if (res.ok && (r.mode === "navigate" || /\\.png$/.test(r.url))) { const cp = res.clone(); caches.open(C).then(c => c.put(r.mode === "navigate" ? "/" : r, cp)); } return res; })
    .catch(() => caches.match(r.mode === "navigate" ? "/" : r)));
