const TR = (() => {
  if (LANG === "fr") return null;
  const col = LANG === "en" ? 1 : 2, exact = new Map(), upper = new Map(), pats = [];
  const esc = x => x.replace(/[.*+?^$()|[\\]\\\\{}]/g, "\\\\$&");
  for (const row of I18N_DATA) {
    const fr = row[0], to = row[col];
    if (!to || to === fr) continue;
    if (fr.includes("{}")) {
      const lit = fr.replace(/\\{\\}/g, "");
      if (lit.replace(/[^A-Za-zÀ-ÿ]/g, "").length < 3) continue;
      pats.push([new RegExp("^" + fr.split("{}").map(esc).join("([\\\\s\\\\S]*?)") + "$"), to, lit.length]);
    } else { exact.set(fr, to); if (fr !== fr.toUpperCase()) upper.set(fr.toUpperCase(), to.toUpperCase()); }
  }
  pats.sort((a, b) => b[2] - a[2]);          // les phrases les plus précises d'abord
  for (const [k, v] of upper) if (!exact.has(k)) exact.set(k, v);   // mêmes textes écrits en MAJUSCULES
  return { exact, pats, cache: new Map() };
})();
function tr(s) {
  if (!TR || typeof s !== "string" || !/[A-Za-zÀ-ÿ]/.test(s)) return s;
  const c = TR.cache.get(s);
  if (c !== undefined) return c;
  const core = s.trim(), lead = s.slice(0, s.indexOf(core)), trail = s.slice(s.indexOf(core) + core.length);
  let out = TR.exact.get(core);
  if (out === undefined) for (const [re, to] of TR.pats) {
    const m = re.exec(core);
    if (m) { let i = 1; out = to.replace(/\\{\\}/g, () => tr(m[i++] || "")); break; }
  }
  if (out === undefined && core.includes(" · ")) {               // "SEIZIÈMES DE FINALE · 1'" : on traduit chaque morceau
    const parts = core.split(" · "), done = parts.map(x => tr(x));
    if (done.some((x, i) => x !== parts[i])) out = done.join(" · ");
  }
  const res = out === undefined ? s : lead + out + trail;
  if (TR.cache.size > 5000) TR.cache.clear();
  TR.cache.set(s, res);
  return res;
}
if (TR) {
  document.documentElement.lang = LANG;
  // texte dessiné dans le match (tableau des scores, messages, boutons tactiles...)
  const P = CanvasRenderingContext2D.prototype;
  for (const f of ["fillText", "strokeText"]) { const o = P[f]; P[f] = function (t, ...a) { return o.call(this, tr(String(t)), ...a); }; }
  const om = P.measureText; P.measureText = function (t) { return om.call(this, tr(String(t))); };
  for (const f of ["confirm", "prompt", "alert"]) { const o = window[f]; if (o) window[f] = (msg, ...a) => o.call(window, tr(String(msg)), ...a); }
  // texte des menus et des fenêtres
  const trText = n => { const p = n.parentNode; if (!p || p.nodeName === "SCRIPT" || p.nodeName === "STYLE" || p.nodeName === "TEXTAREA") return; const t = tr(n.nodeValue); if (t !== n.nodeValue) n.nodeValue = t; };
  const trDom = root => {
    const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    let n; while ((n = w.nextNode())) trText(n);
    if (root.querySelectorAll) for (const el of [root, ...root.querySelectorAll("[placeholder],[title],[aria-label]")]) for (const a of ["placeholder", "title", "aria-label"]) {
      const v = el.getAttribute && el.getAttribute(a); if (v) { const t = tr(v); if (t !== v) el.setAttribute(a, t); }
    }
  };
  trDom(document.body);
  new MutationObserver(ms => {
    for (const m of ms) {
      if (m.type === "characterData") trText(m.target);
      else for (const a of m.addedNodes) { if (a.nodeType === 3) trText(a); else if (a.nodeType === 1) trDom(a); }
    }
  }).observe(document.body, { childList: true, subtree: true, characterData: true });
}
