    showGameMsg("🔨 MARTEAU DE BANNISSEMENT !", BLOOD, 1.2);
    beep(70, 0.35, "sawtooth", 0.08); setTimeout(() => beep(55, 0.4, "sawtooth", 0.08), 180);
    return;
