  const SLOT = [{ gx: -1.05, gz: -0.2, side: -1, at: 0.7 }, { gx: 1.05, gz: -0.2, side: 1, at: 0.85 }, { gx: 0.5, gz: -0.75, side: 1, at: 1.05 }];
