  return [...Array(NB_CLUBS).keys()].slice(0, 8).map(i => ({ n: TEAMS[CLUB0 + i].name, c1: TEAMS[CLUB0 + i].c1, c2: TEAMS[CLUB0 + i].c2, s: 80 + (i % 5), real: CLUB0 + i }));
